import { useState, useCallback } from 'react';
import { WalletInitializationError } from '../../../base/errors/index.js';
import { useSolanaWallet } from './useSolanaWallet.js';
import { walletSignAndSendTransaction } from '../../../base/wallet/solana.js';

const useSignAndSendTransaction = () => {
  const {
    solanaWallet
  } = useSolanaWallet();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [data, setData] = useState(null);
  const signAndSendTransaction = useCallback(async transaction => {
    setLoading(true);
    setError(null);
    try {
      if (!solanaWallet) throw WalletInitializationError.notReady();
      const signature = await walletSignAndSendTransaction(solanaWallet, transaction);
      setData(signature);
      return signature;
    } catch (err) {
      setError(err);
    } finally {
      setLoading(false);
    }
  }, [solanaWallet]);
  return {
    loading,
    error,
    data,
    signAndSendTransaction
  };
};

export { useSignAndSendTransaction };
